// â”€â”€â”€ Generate Schema (main pipeline) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export async function generateSchemaFromPrompt(
  rawPrompt: string,
): Promise<GenerateResult | null> {
  // Step 1: Normalize
  const normalized = normalizePrompt(rawPrompt);

  // Step 2: DB prompt cache check
  const cached = await promptCacheGet(normalized, "generate");
  if (cached) {
    const cachedResult = cached as GenerateResult;
    return {
      ...cachedResult,
      meta: {
        ...(cachedResult.meta ?? {}),
        cacheHit: true,
        cacheTier: "db",
        promptScore: cachedResult.meta?.promptScore ?? 0,
      },
    };
  }

  // Step 3: Rule engine score
  const ruleScore = scorePrompt(rawPrompt);
  if (ruleScore.score < 10) {
    return null; // Prompt too weak â€” reject early
  }

  // Step 4: Template detection
  const matchedTemplates = detectTemplates(rawPrompt);
  let templateBase: Partial<GenerateResult> | null = null;
  if (matchedTemplates.length > 0) {
    templateBase = loadTemplate(matchedTemplates);
  }

  // Step 5: Entity expansion
  const expandedEntities = expandEntities(rawPrompt);

  // Step 6: Build enriched prompt for AI
  const expandedNote =
    expandedEntities.length > 0
      ? `\n\nAlso include expanded entities: ${expandedEntities.join(", ")}.`
      : "";

  const templateNote =
    matchedTemplates.length > 0
      ? `\n\nBase this on a ${matchedTemplates.join(" + ")} schema pattern.`
      : "";

  const enrichedPrompt = `${rawPrompt}${templateNote}${expandedNote}`;

  // If template gives a full schema, use it as a seed and refine with AI
  const messages: GroqMessage[] = [
    { role: "system", content: buildGenerateSystemPrompt() },
    {
      role: "user",
      content: templateBase
        ? `Refine and expand this schema for: ${enrichedPrompt}\n\nSeed schema:\n${JSON.stringify(templateBase)}`
        : `Generate a complete database schema for: ${enrichedPrompt}`,
    },
  ];

  // Step 7: AI call
  const aiResult = await chatJsonWithFallback<GenerateResult>(messages, {
    temperature: 0.2,
    maxTokens: 16384,
  });

  if (!aiResult || !aiResult.nodes) return null;

  // Step 8.5: Validate completeness (new!) â€” check if all requested entities are present
  let completenessReport = validateCompletenessOfSchema(
    rawPrompt,
    aiResult.nodes,
  );
  let correctionAttempts = 0;

  // Auto-correct if incomplete and under attempt limit
  const MAX_CORRECTIONS = 1; // Try once to correct missing tables
  if (!completenessReport.isComplete && correctionAttempts < MAX_CORRECTIONS) {
    console.log(
      `âš ï¸  Schema incomplete (${completenessReport.matchPercentage.toFixed(0)}% match). Attempting auto-correction...`,
    );

    const correctivePrompt = generateCorrectivePrompt(
      rawPrompt,
      completenessReport,
    );
    const correctionMessages: GroqMessage[] = [
      { role: "system", content: buildGenerateSystemPrompt() },
      {
        role: "user",
        content: correctivePrompt,
      },
    ];

    const correctedResult = await chatJsonWithFallback<GenerateResult>(
      correctionMessages,
      {
        temperature: 0.2,
        maxTokens: 16384,
      },
    );

    if (correctedResult?.nodes) {
      // Validate the corrected result
      const updatedReport = validateCompletenessOfSchema(
        rawPrompt,
        correctedResult.nodes,
      );

      if (
        updatedReport.isComplete ||
        updatedReport.matchPercentage > completenessReport.matchPercentage
      ) {
        // Use corrected result
        Object.assign(aiResult, correctedResult);
        completenessReport = updatedReport;
        correctionAttempts++;

        console.log(
          `âœ… Auto-correction successful! Match improved to ${completenessReport.matchPercentage.toFixed(0)}%`,
        );
      }
    }
  }

  // Step 8: Post-process â€” constraint + relationship inference
  const constraints = inferConstraints(aiResult.nodes);
  const extraEdges = inferRelationships(aiResult.nodes, aiResult.edges ?? []);

  // Step 9: Intelligence layers
  const normalizationHints = generateNormalizationHints(aiResult.nodes);
  const indexSuggestions = generateIndexSuggestions(
    aiResult.nodes,
    aiResult.edges ?? [],
  );
  const queryWarnings = analyzeQueryPatterns(
    aiResult.nodes,
    aiResult.edges ?? [],
  );
  const joinComplexity = detectJoinComplexity(aiResult.edges ?? []);
  const nPlusOneRisks = detectNPlusOne(aiResult.nodes, aiResult.edges ?? []);

  const result: GenerateResult = {
    nodes: aiResult.nodes,
    edges: [...(aiResult.edges ?? []), ...extraEdges],
    meta: {
      cacheHit: false,
      templateMatched:
        matchedTemplates.length > 0 ? matchedTemplates : undefined,
      promptScore: ruleScore.score,
      normalizationHints,
      indexSuggestions,
      queryWarnings: [...queryWarnings, ...joinComplexity],
      nPlusOneRisks,
      completeness: {
        isComplete: completenessReport.isComplete,
        requestedEntities: completenessReport.requestedEntities,
        generatedTables: completenessReport.generatedTables,
        missingTables: completenessReport.missingTables,
        matchPercentage: completenessReport.matchPercentage,
        correctionAttempts,
      },
    },
  };

  // Apply inferred constraints to edges
  if (constraints.length > 0) {
    result.edges = result.edges.map((edge) => {
      const constraint = constraints.find(
        (c) => c.sourceTable === edge.source && c.targetTable === edge.target,
      );
      if (constraint && edge.data) {
        edge.data.onDelete = constraint.onDelete;
      }
      return edge;
    });
  }

  // Step 10: Write to DB cache
  await promptCacheSet(normalized, "generate", result);

  return result;
}

// â”€â”€â”€ Analyze Schema â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export async function analyzeSchema(
  schemaJson: unknown,
): Promise<unknown | null> {
  const cached = await promptCacheGet(JSON.stringify(schemaJson), "analyze");
  if (cached) return cached;

  const messages: GroqMessage[] = [
    { role: "system", content: buildAnalyzeSystemPrompt() },
    {
      role: "user",
      content: `Analyze this schema:\n${JSON.stringify(schemaJson, null, 2)}`,
    },
  ];

  const result = await chatJsonWithFallback(messages, {
    temperature: 0.1,
    maxTokens: 600,
  });
  if (result)
    await promptCacheSet(JSON.stringify(schemaJson), "analyze", result);
  return result;
}

// â”€â”€â”€ Refine Prompt â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export async function refinePrompt(rawPrompt: string): Promise<unknown | null> {
  const cached = await promptCacheGet(rawPrompt, "refine");
  if (cached) return cached;

  const messages: GroqMessage[] = [
    { role: "system", content: buildRefineSystemPrompt() },
    {
      role: "user",
      content: `Improve this database design prompt: "${rawPrompt}"`,
    },
  ];

  const result = await chatJsonWithFallback(messages, {
    temperature: 0.4,
    maxTokens: 1024,
  });
  if (result) await promptCacheSet(rawPrompt, "refine", result);
  return result;
}

// â”€â”€â”€ Review Schema â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export async function reviewSchema(
  schemaJson: unknown,
  context?: string,
): Promise<unknown | null> {
  const cacheKey = JSON.stringify(schemaJson) + (context ?? "");
  const cached = await promptCacheGet(cacheKey, "review");
  if (cached) return cached;

  const userContent = context
    ? `Review this schema for a ${context} application:\n${JSON.stringify(schemaJson, null, 2)}`
    : `Review this database schema:\n${JSON.stringify(schemaJson, null, 2)}`;

  const messages: GroqMessage[] = [
    { role: "system", content: buildReviewSystemPrompt() },
    { role: "user", content: userContent },
  ];

  const result = await chatJsonWithFallback(messages, {
    temperature: 0.2,
    maxTokens: 2048,
  });
  if (result) await promptCacheSet(cacheKey, "review", result);
  return result;
}

// â”€â”€â”€ AI Client Factory â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//
// Abstraction layer that returns either Groq or Local LLM client based on config.
// Both clients implement the same interface, so existing code is fully compatible.
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import type { GroqMessage, GroqChatOptions } from "./groqClient";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export interface AIClient {
  chatJson<T = any>(
    messages: GroqMessage[],
    options?: GroqChatOptions,
  ): Promise<T | null>;
  isAvailable(): boolean;
}

export type AIProvider = "groq" | "local";

/**
 * Get the configured AI provider from environment
 * Defaults to "groq" for backwards compatibility
 */
export function getAIProvider(): AIProvider {
  const provider = process.env.AI_PROVIDER as AIProvider;
  return provider === "local" ? "local" : "groq";
}

/**
 * Factory function that returns the appropriate client
 * Lazy-loads the client only when needed
 */
let cachedClient: AIClient | null = null;

export function getAIClient(): AIClient {
  // Return cached client if already initialized
  if (cachedClient) {
    return cachedClient;
  }

  const provider = getAIProvider();

  if (provider === "local") {
    const { createLocalLLMClient } = require("./localLLMClient");
    cachedClient = createLocalLLMClient();
  } else {
    // Default: Groq (backwards compatible)
    const { groqChatJson, isGroqAvailable } = require("./groqClient");
    cachedClient = {
      chatJson: groqChatJson,
      isAvailable: isGroqAvailable,
    } as AIClient;
  }

  return (
    cachedClient ?? { chatJson: async () => null, isAvailable: () => false }
  );
}

/**
 * Check if the current AI provider is available
 */
export function isAIProviderAvailable(): boolean {
  const client = getAIClient();
  return client.isAvailable();
}

/**
 * Reset cache (useful for testing or switching providers at runtime)
 */
export function resetAIClientCache(): void {
  cachedClient = null;
}

// â”€â”€â”€ Groq Client Wrapper â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//
// Wraps the groq-sdk with key rotation, retry logic, and JSON enforcement.
// Model: llama3-70b-8192 (configurable via GROQ_MODEL env var)
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import Groq from "groq-sdk";
import {
  getActiveKey,
  recordKeyUsage,
  markKeyRateLimited,
  isGroqAvailable,
} from "./keyManager";
import { validateJsonResponse } from "../utils/jsonValidator";
import {
  stripMarkdownFences,
  repairTruncatedJson,
} from "../utils/jsonValidator";

export { isGroqAvailable };

const DEFAULT_MODEL = "llama-3.1-8b-instant";
const MAX_RETRIES = 3;
const BASE_BACKOFF_MS = 2000;

export interface GroqMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface GroqChatOptions {
  temperature?: number;
  maxTokens?: number;
  /** If true, the system prompt will instruct strict JSON-only output */
  requireJson?: boolean;
}

// â”€â”€â”€ Singleton client factory â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

function makeClient(apiKey: string): Groq {
  return new Groq({ apiKey });
}

// â”€â”€â”€ Parse retry-after from Groq 429 header/message â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

function parseRetryAfter(err: unknown): number {
  if (err && typeof err === "object") {
    const e = err as Record<string, unknown>;
    // groq-sdk puts the header value in e.headers
    const headers = e["headers"] as Record<string, string> | undefined;
    if (headers?.["retry-after"]) {
      const secs = parseFloat(headers["retry-after"]);
      if (!isNaN(secs)) return Math.ceil(secs * 1000);
    }
    // Fallback: scan message string
    const msg = String(e["message"] ?? "");
    const match = msg.match(/retry.{0,10}?(\d+(?:\.\d+)?)\s*s/i);
    if (match) return Math.ceil(parseFloat(match[1]) * 1000);
  }
  return 60_000; // default 60s penalty
}

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

// â”€â”€â”€ Core chat function â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export async function groqChat(
  messages: GroqMessage[],
  options: GroqChatOptions = {},
): Promise<string | null> {
  if (!isGroqAvailable()) {
    console.error("[GroqClient] No Groq API keys configured.");
    return null;
  }

  const model = process.env.GROQ_MODEL ?? DEFAULT_MODEL;
  const { temperature = 0.3, maxTokens = 4096, requireJson = true } = options;

  // Inject JSON enforcement into system message if required
  let finalMessages = [...messages];
  if (requireJson) {
    const systemIdx = finalMessages.findIndex((m) => m.role === "system");
    const jsonInstruction =
      "\n\nCRITICAL: Return ONLY valid JSON. No explanations, no markdown fences, no extra text outside the JSON object.";
    if (systemIdx >= 0) {
      finalMessages[systemIdx] = {
        ...finalMessages[systemIdx],
        content: finalMessages[systemIdx].content + jsonInstruction,
      };
    } else {
      finalMessages = [
        {
          role: "system",
          content:
            "You are a precise JSON-generating assistant." + jsonInstruction,
        },
        ...finalMessages,
      ];
    }
  }

  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
    const apiKey = getActiveKey();
    if (!apiKey) {
      console.error("[GroqClient] No available API key.");
      return null;
    }

    try {
      const client = makeClient(apiKey);
      const completion = await client.chat.completions.create({
        model,
        messages: finalMessages as Groq.Chat.ChatCompletionMessageParam[],
        temperature,
        max_tokens: maxTokens,
      });

      recordKeyUsage();

      const content = completion.choices[0]?.message?.content ?? null;
      return content;
    } catch (err: unknown) {
      const e = err as Record<string, unknown>;
      const status = e["status"] as number | undefined;

      if (status === 429) {
        const waitMs = parseRetryAfter(err);
        markKeyRateLimited(waitMs);
        console.warn(
          `[GroqClient] Rate limited on attempt ${attempt + 1}. Waiting ${waitMs}ms before retry.`,
        );
        await sleep(waitMs > 30_000 ? BASE_BACKOFF_MS * (attempt + 1) : waitMs);
        continue;
      }

      // Non-retryable errors
      console.error(`[GroqClient] Error on attempt ${attempt + 1}:`, err);
      if (attempt < MAX_RETRIES - 1) {
        await sleep(BASE_BACKOFF_MS * (attempt + 1));
      }
    }
  }

  console.error("[GroqClient] All retry attempts exhausted.");
  return null;
}

// â”€â”€â”€ JSON-extracting wrapper â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

/**
 * Call Groq and return a parsed JSON object. Returns null on failure.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export async function groqChatJson<T = any>(
  messages: GroqMessage[],
  options: GroqChatOptions = {},
): Promise<T | null> {
  const raw = await groqChat(messages, { ...options, requireJson: true });
  if (!raw) return null;

  const cleaned = stripMarkdownFences(raw);
  const validated = validateJsonResponse<T>(cleaned);
  if (validated !== null) return validated;

  const repaired = repairTruncatedJson(cleaned);
  if (repaired) {
    const revalidated = validateJsonResponse<T>(repaired);
    if (revalidated !== null) return revalidated;
  }

  console.warn(
    "[GroqClient] Could not parse JSON from response:",
    raw.slice(0, 300),
  );
  return null;
}

// â”€â”€â”€ Local LLM Client â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//
// Wrapper for local LLM endpoints (Ollama, LM Studio, LocalAI, etc.)
// Implements the same interface as groqClient for seamless switching.
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import type { GroqMessage, GroqChatOptions } from "./groqClient";
import {
  stripMarkdownFences,
  repairTruncatedJson,
  extractJsonObject,
  validateJsonResponse,
} from "../utils/jsonValidator";

const DEFAULT_MODEL = "mistral";
const MAX_RETRIES = 2;
const BASE_BACKOFF_MS = 1000;
const DEFAULT_TIMEOUT_MS = 25000;

/**
 * Create a local LLM client (Ollama-compatible)
 * URL should be something like: http://192.168.x.x:11434
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function createLocalLLMClient(): {
  chatJson<T = any>(
    messages: GroqMessage[],
    options?: GroqChatOptions,
  ): Promise<T | null>;
  isAvailable(): boolean;
} {
  const baseUrl = process.env.LOCAL_LLM_URL || "http://localhost:11434";
  const model = process.env.LOCAL_LLM_MODEL || DEFAULT_MODEL;

  return {
    chatJson,
    isAvailable,
  };

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  async function chatJson<T = any>(
    messages: GroqMessage[],
    options?: GroqChatOptions,
  ): Promise<T | null> {
    const temperature = options?.temperature ?? 0.3;
    const maxTokens = options?.maxTokens ?? 4096;

    // Add JSON instruction if requested
    let msgs = [...messages];
    if (options?.requireJson !== false) {
      const lastIdx = msgs.length - 1;
      msgs[lastIdx] = {
        ...msgs[lastIdx],
        content:
          msgs[lastIdx].content +
          "\n\nCRITICAL: Return ONLY valid JSON. No explanations, no markdown fences, no extra text outside the JSON object.",
      };
    }

    let lastError: Error | null = null;

    for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
      try {
        const response = await callLocalLLM(baseUrl, model, msgs, {
          temperature,
          max_tokens: maxTokens,
        });

        // Parse and validate the response
        let cleaned = stripMarkdownFences(response.message.content);

        // Try to validate raw first
        const validated = validateJsonResponse<T>(cleaned);
        if (validated !== null) return validated;

        // Try repair if validation failed
        const repaired = repairTruncatedJson(cleaned);
        if (repaired) {
          const revalidated = validateJsonResponse<T>(repaired);
          if (revalidated !== null) return revalidated;
        }

        // Tolerant fallback: extract first JSON object/array from mixed text.
        const extracted = extractJsonObject(cleaned) as T | null;
        if (extracted !== null) return extracted;

        // Parsing failed: do not keep regenerating large responses; fail fast.
        return null;
      } catch (error) {
        lastError = error as Error;

        // If it's a network error, retry with backoff
        if (
          lastError.message.includes("fetch") ||
          lastError.message.includes("connection") ||
          lastError.message.includes("ECONNREFUSED")
        ) {
          if (attempt < MAX_RETRIES - 1) {
            const backoff = BASE_BACKOFF_MS * Math.pow(2, attempt);
            await sleep(backoff);
            continue;
          }
        }

        // For other errors, log and retry
        if (attempt < MAX_RETRIES - 1) {
          const backoff = BASE_BACKOFF_MS * Math.pow(2, attempt);
          await sleep(backoff);
          continue;
        }

        break;
      }
    }

    console.error(
      `[LocalLLM] Failed after ${MAX_RETRIES} retries:`,
      lastError?.message,
    );
    return null;
  }

  function isAvailable(): boolean {
    // For local LLM, assume available if URL is configured
    // A more robust check would be async, but keep sync for interface compatibility
    return (
      baseUrl !== "http://localhost:11434" ||
      process.env.LOCAL_LLM_URL !== undefined
    );
  }
}

/**
 * Call the local LLM endpoint (Ollama-compatible API)
 */
async function callLocalLLM(
  baseUrl: string,
  model: string,
  messages: GroqMessage[],
  options: { temperature: number; max_tokens: number },
): Promise<{ message: { content: string } }> {
  const url = `${baseUrl}/api/chat`;
  const timeoutMs = Number(
    process.env.LOCAL_LLM_TIMEOUT_MS ?? DEFAULT_TIMEOUT_MS,
  );

  const response = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    signal: AbortSignal.timeout(timeoutMs),
    body: JSON.stringify({
      model,
      messages,
      temperature: options.temperature,
      stream: false,
      format: "json",
      options: {
        num_predict: options.max_tokens,
      },
    }),
  });

  if (!response.ok) {
    throw new Error(
      `Local LLM error: ${response.status} ${response.statusText}`,
    );
  }

  const data = await response.json();
  return data;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

