export type TemplateName =
  | "ecommerce"
  | "blog"
  | "saas"
  | "restaurant"
  | "inventory"
  | "social_network";

interface TemplateSignature {
  name: TemplateName;
  /** Any of these phrases triggers the template */
  phrases: string[];
  /** Must NOT contain these to avoid false positives */
  excludePhrases?: string[];
}

const TEMPLATES: TemplateSignature[] = [
  {
    name: "ecommerce",
    phrases: [
