/**
 * Detect primary entities in the prompt and return their expanded sub-entities.
 * Returns a deduplicated list of sub-entity names to add to the schema.
 */
export function expandEntities(prompt: string): string[] {
  const lower = prompt.toLowerCase().replace(/[^\w\s]/g, " ");
  const tokens = lower.split(/\s+/);

  const detectedEntities = new Set<string>();
  for (const token of tokens) {
    const entity = ENTITY_TRIGGERS[token];
    if (entity) detectedEntities.add(entity);
  }

  const expanded = new Set<string>();
  for (const entity of detectedEntities) {
    const expansions = EXPANSION_RULES[entity] ?? [];
    for (const sub of expansions) {
      // Only add if not already in the detected primary entities
      if (!detectedEntities.has(sub)) {
        expanded.add(sub);
      }
    }
  }

  return Array.from(expanded);
}

/**
 * Get the full expansion map for a specific entity.
 */
export function getEntityExpansion(entity: string): string[] {
  return EXPANSION_RULES[entity.toLowerCase()] ?? [];
}

// â”€â”€â”€ Constraint Inference â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//
// Infers appropriate ON DELETE behaviors and column constraints
// based on table/column naming conventions.
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import type { SchemaNode, SchemaEdge } from "../ai/types";

export interface InferredConstraint {
  sourceTable: string;
  targetTable: string;
  onDelete: "CASCADE" | "SET NULL" | "RESTRICT" | "NO ACTION";
  reason: string;
}

// Tables where CASCADE delete is safe (child records follow parent)
const CASCADE_TARGETS = new Set([
  "order_items",
  "order_lines",
  "cart_items",
  "wishlist_items",
  "post_tags",
  "post_categories",
  "article_tags",
  "comment_votes",
  "task_assignments",
  "task_comments",
  "attachments",
  "message_reads",
  "lesson_progress",
  "course_modules",
  "medical_records",
  "reservation_guests",
  "hotel_rooms",
  "room_amenities",
  "shipment_items",
  "shipment_tracking",
  "stock_levels",
  "recipe_ingredients",
  "recipe_steps",
  "menu_items",
  "order_lines",
  "follows",
  "likes",
  "sessions",
  "notifications",
  "audit_logs",
]);

// Tables where we should SET NULL (keep the record, remove reference)
const SET_NULL_TARGETS = new Set([
  "orders",
  "invoices",
  "payments",
  "subscriptions",
  "appointments",
  "reservations",
  "bookings",
]);

// Tables where we should RESTRICT (prevent deletion)
const RESTRICT_TARGETS = new Set([
  "products",
  "users",
  "employees",
  "customers",
  "warehouses",
  "suppliers",
  "accounts",
]);

/**
 * Given the list of nodes and edges in a schema, infer constraint recommendations.
 */
export function inferConstraints(
  nodes: SchemaNode[],
  edges?: SchemaEdge[],
): InferredConstraint[] {
  const result: InferredConstraint[] = [];
  const nodeIds = new Set(nodes.map((n) => n.id));

  for (const node of nodes) {
    const tableName = node.id.toLowerCase();

    // Find FK columns in this table
    for (const col of node.data.columns) {
      if (!col.isForeignKey) continue;

      // Infer target table from FK column naming
      const refTable = col.name.replace(/_id$/, "");
      if (!nodeIds.has(refTable)) continue;

      let onDelete: InferredConstraint["onDelete"] = "NO ACTION";
      let reason = "Default behavior";

      if (CASCADE_TARGETS.has(tableName)) {
        onDelete = "CASCADE";
        reason = `${tableName} is a child/detail table â€” cascade deletes are appropriate`;
      } else if (SET_NULL_TARGETS.has(tableName)) {
        onDelete = "SET NULL";
        reason = `${tableName} should preserve records even when referenced entity is deleted`;
      } else if (RESTRICT_TARGETS.has(refTable)) {
        onDelete = "RESTRICT";
        reason = `${refTable} is a core entity â€” prevent accidental deletion`;
      } else if (tableName.endsWith("_items") || tableName.endsWith("_lines")) {
        onDelete = "CASCADE";
        reason = "Line/item tables typically cascade with their parent";
      }

      result.push({
        sourceTable: node.id,
        targetTable: refTable,
        onDelete,
        reason,
      });
    }
  }

  return result;
}

/**
 * Generate human-readable constraint suggestions for the schema health report.
 */
export function generateConstraintSuggestions(nodes: SchemaNode[]): string[] {
  const suggestions: string[] = [];

  for (const node of nodes) {
    const hasCreatedAt = node.data.columns.some((c) => c.name === "created_at");
    const hasUpdatedAt = node.data.columns.some((c) => c.name === "updated_at");

    if (!hasCreatedAt) {
      suggestions.push(
        `Table "${node.data.label}" is missing a created_at timestamp column.`,
      );
    }
    if (
      !hasUpdatedAt &&
      ["users", "products", "orders", "accounts"].includes(node.id)
    ) {
      suggestions.push(
        `Table "${node.data.label}" should include an updated_at timestamp.`,
      );
    }

    const pkCols = node.data.columns.filter((c) => c.isPrimaryKey);
    if (pkCols.length === 0) {
      suggestions.push(
        `Table "${node.data.label}" has no primary key â€” add an id SERIAL PRIMARY KEY.`,
      );
    }
  }

  return suggestions;
}

// â”€â”€â”€ Pattern-based Relationship Inference â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//
// Infers missing foreign-key relationships by analyzing FK column naming
// conventions in the schema nodes. Adds edges that weren't returned by AI.
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import type { SchemaNode, SchemaEdge } from "../ai/types";

/**
 * Scan all FK columns and infer edges for any relationships not already present.
 */
export function inferRelationships(
  nodes: SchemaNode[],
  existingEdges: SchemaEdge[],
): SchemaEdge[] {
  const tableIds = new Set(nodes.map((n) => n.id));
  const existingPairs = new Set(
    existingEdges.map((e) => `${e.source}->${e.target}`),
  );

  const inferred: SchemaEdge[] = [];

  for (const node of nodes) {
    for (const col of node.data.columns) {
      if (!col.isForeignKey) continue;

      // Derive target table from FK column name (e.g., user_id -> users, author_id -> users)
      const colLower = col.name.toLowerCase();
      const withoutId = colLower.replace(/_id$/, "");

      // Check common plural/singular variants
      const candidates = [
        withoutId,
        withoutId + "s", // user -> users
        withoutId.replace(/y$/, "ies"), // category -> categories
        withoutId.replace(/s$/, ""), // genres -> genre
      ];

      let targetTable: string | null = null;
      for (const cand of candidates) {
        if (tableIds.has(cand) && cand !== node.id) {
          targetTable = cand;
          break;
        }
      }

      if (!targetTable) continue;
      const pairKey = `${node.id}->${targetTable}`;
      if (existingPairs.has(pairKey)) continue;

      // Find target PK column
      const targetNode = nodes.find((n) => n.id === targetTable);
      const targetPk = targetNode?.data.columns.find((c) => c.isPrimaryKey);

      inferred.push({
        id: `inferred_${node.id}_${col.id}`,
        source: node.id,
        target: targetTable,
        sourceHandle: col.id,
        targetHandle: targetPk?.id,
        type: "relationshipEdge",
        data: {
          relationshipType: "one-to-many",
          onDelete: "CASCADE",
        },
      });

      existingPairs.add(pairKey); // Prevent duplicates from multiple FK cols
    }
  }

  return inferred;
}

/**
 * Known relationship patterns based on table name pairs.
 * Returns the expected relationship type for a sourceâ†’target combo.
 */
export function getKnownRelationshipType(
  source: string,
  target: string,
): "one-to-one" | "one-to-many" | "many-to-many" {
  const MANY_TO_MANY_INDICATORS = [
    "tags",
    "categories",
    "roles",
    "permissions",
    "skills",
    "interests",
  ];

  if (
    MANY_TO_MANY_INDICATORS.some((kw) => target.includes(kw)) ||
    // Junction tables often have two FK columns
    (source.includes("_") && source.endsWith("s"))
  ) {
    return "many-to-many";
  }

  const ONE_TO_ONE = [
    ["users", "user_profiles"],
    ["users", "accounts"],
    ["orders", "shipments"],
  ];

  for (const [s, t] of ONE_TO_ONE) {
    if ((source === s && target === t) || (source === t && target === s)) {
      return "one-to-one";
    }
  }

  return "one-to-many";
}

// â”€â”€â”€ Normalization Hints â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//
// Analyzes schema nodes for common normalization violations and generates
// actionable hints (1NF, 2NF, 3NF violations).
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import type { SchemaNode } from "../ai/types";

// Patterns that suggest denormalization or 1NF violation
const MULTI_VALUE_PATTERNS = [
  /tags$/i,
  /categories$/i,
  /list$/i,
  /array$/i,
  /csv$/i,
  /ids$/i,
  /codes$/i,
  /types$/i,
];

// Column naming patterns that suggest a separate table is needed
const COMPUTED_COLUMN_PATTERNS = [
  /total_count$/i,
  /item_count$/i,
  /total_price$/i,
  /full_name$/i,
  /_percentage$/i,
  /_ratio$/i,
];

// Patterns that might indicate 2NF partial dependency
const PARTIAL_DEPENDENCY_PATTERNS = [
  { table: /order_items/, suspect: /product_name|product_price/ },
  { table: /cart_items/, suspect: /product_name|price/ },
  { table: /invoice_items/, suspect: /description|unit_price/ },
];

/**
 * Generate normalization hints for a given schema.
 */
export function generateNormalizationHints(nodes: SchemaNode[]): string[] {
  const hints: string[] = [];

  for (const node of nodes) {
    const tableName = node.id.toLowerCase();
    const colNames = node.data.columns.map((c) => c.name.toLowerCase());

    // 1NF: Check for multi-value columns
    for (const col of node.data.columns) {
      const colLower = col.name.toLowerCase();
      if (MULTI_VALUE_PATTERNS.some((p) => p.test(colLower))) {
        hints.push(
          `[1NF] "${node.data.label}.${col.name}" may store multiple values â€” consider a junction/child table instead.`,
        );
      }
    }

    // 1NF: Check for columns named like "address1", "address2", "phone1", "phone2"
    const numberedCols = colNames.filter((c) => /[a-z]_?[12]$/.test(c));
    if (numberedCols.length >= 2) {
      hints.push(
        `[1NF] "${node.data.label}" has numbered columns (${numberedCols.join(", ")}) â€” normalize into a child table.`,
      );
    }

    // 2NF: Check for partial dependencies in composite-key-prone tables
    for (const { table, suspect } of PARTIAL_DEPENDENCY_PATTERNS) {
      if (table.test(tableName)) {
        const suspected = node.data.columns.filter((c) => suspect.test(c.name));
        if (suspected.length > 0) {
          hints.push(
            `[2NF] "${node.data.label}" contains columns (${suspected.map((c) => c.name).join(", ")}) that depend on the referenced entity, not the composite key â€” consider denoting them via JOIN instead.`,
          );
        }
      }
    }

    // 3NF: Check for computed / derived columns
    for (const col of node.data.columns) {
      if (COMPUTED_COLUMN_PATTERNS.some((p) => p.test(col.name))) {
        hints.push(
          `[3NF] "${node.data.label}.${col.name}" appears to be a computed/derived column â€” remove it and compute at query time to avoid update anomalies.`,
        );
      }
    }

    // 3NF: Check for transitive dependency indicators (status_label alongside status_code)
    const hasBothCodeAndLabel =
      colNames.some((c) => c.endsWith("_code")) &&
      colNames.some((c) => c.endsWith("_label") || c.endsWith("_name"));
    if (hasBothCodeAndLabel) {
      hints.push(
        `[3NF] "${node.data.label}" may have transitive dependencies (code + label columns) â€” consider a lookup/reference table.`,
      );
    }

    // Missing timestamps
    const hasCreatedAt = colNames.includes("created_at");
    if (!hasCreatedAt && node.data.columns.length > 2) {
      hints.push(
        `"${node.data.label}" is missing a created_at timestamp â€” add one to track record creation time.`,
      );
    }
  }

  return hints;
}

// â”€â”€â”€ Index Suggestions â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//
// Analyzes schema nodes and edges to recommend database indexes that will
// improve query performance.
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import type { SchemaNode, SchemaEdge } from "../ai/types";

export interface IndexSuggestion {
  table: string;
  column: string;
  type: "btree" | "unique" | "composite";
  reason: string;
}

// Columns that almost always need an index
const AUTO_INDEX_PATTERNS = [
  {
    pattern: /^email$/i,
    type: "unique" as const,
    reason: "Email lookups require unique index for fast auth queries",
  },
  {
    pattern: /^username$/i,
    type: "unique" as const,
    reason: "Username lookups for login/profile require unique index",
  },
  {
    pattern: /^slug$/i,
    type: "unique" as const,
    reason: "URL slug lookups require unique index",
  },
  {
    pattern: /^status$/i,
    type: "btree" as const,
    reason: "Status filtering is a common query pattern",
  },
  {
    pattern: /^created_at$/i,
    type: "btree" as const,
    reason: "Date-range queries on created_at benefit from a btree index",
  },
  {
    pattern: /^published_at$/i,
    type: "btree" as const,
    reason: "Sorting and filtering by publish date requires index",
  },
  {
    pattern: /^starts_at$/i,
    type: "btree" as const,
    reason: "Time-based range queries need index",
  },
  {
    pattern: /^ends_at$/i,
    type: "btree" as const,
    reason: "Time-based range queries need index",
  },
  {
    pattern: /^type$/i,
    type: "btree" as const,
    reason: "Type discriminator columns are frequently filtered",
  },
  {
    pattern: /^role$/i,
    type: "btree" as const,
    reason: "Role-based filtering benefits from index",
  },
  {
    pattern: /^token$/i,
    type: "unique" as const,
    reason: "Token lookups (auth, reset) require unique index",
  },
  {
    pattern: /^sku$/i,
    type: "unique" as const,
    reason: "SKU lookups require unique index for inventory",
  },
  {
    pattern: /^barcode$/i,
    type: "unique" as const,
    reason: "Barcode scans require unique index",
  },
];

/**
 * Generate index recommendations for the schema.
 */
export function generateIndexSuggestions(
  nodes: SchemaNode[],
  edges: SchemaEdge[],
): string[] {
  const suggestions: string[] = [];

  for (const node of nodes) {
    const tableName = node.data.label;

    // 1. Foreign key columns always need indexes
    for (const col of node.data.columns) {
      if (col.isForeignKey) {
        suggestions.push(
          `CREATE INDEX idx_${node.id}_${col.name} ON ${tableName} (${col.name}); â€” Foreign key column needs index to speed up JOIN and CASCADE operations.`,
        );
      }
    }

    // 2. Auto-index well-known columns
    for (const col of node.data.columns) {
      if (col.isPrimaryKey || col.isForeignKey) continue;
      for (const { pattern, type, reason } of AUTO_INDEX_PATTERNS) {
        if (pattern.test(col.name)) {
          const directive =
            type === "unique" ? "CREATE UNIQUE INDEX" : "CREATE INDEX";
          suggestions.push(
            `${directive} idx_${node.id}_${col.name} ON ${tableName} (${col.name}); â€” ${reason}.`,
          );
          break;
        }
      }
    }

    // 3. Composite index for common filter+sort patterns
    const statusCol = node.data.columns.find((c) => /^status$/i.test(c.name));
    const createdCol = node.data.columns.find((c) =>
      /^created_at$/i.test(c.name),
    );
    if (statusCol && createdCol) {
      suggestions.push(
        `CREATE INDEX idx_${node.id}_status_created ON ${tableName} (status, created_at); â€” Composite index for "filter by status + sort by date" queries.`,
      );
    }

    // 4. Full-text search hints for TEXT columns
    const textCols = node.data.columns.filter(
      (c) => c.type === "TEXT" && !c.isPrimaryKey && c.name !== "body",
    );
    if (
      textCols.length > 0 &&
      ["posts", "articles", "products", "documents"].includes(node.id)
    ) {
      suggestions.push(
        `Consider a GIN index on ${tableName} for full-text search across (${textCols.map((c) => c.name).join(", ")}).`,
      );
    }
  }

  return suggestions;
}

/**
 * Returns structured index suggestions (for programmatic use).
 */
export function getStructuredIndexSuggestions(
  nodes: SchemaNode[],
  edges: SchemaEdge[],
): IndexSuggestion[] {
  const result: IndexSuggestion[] = [];

  for (const node of nodes) {
    for (const col of node.data.columns) {
      if (col.isForeignKey) {
        result.push({
          table: node.id,
          column: col.name,
          type: "btree",
          reason: "Foreign key â€” needed for JOIN performance",
        });
      }
      for (const { pattern, type, reason } of AUTO_INDEX_PATTERNS) {
        if (pattern.test(col.name) && !col.isPrimaryKey && !col.isForeignKey) {
          result.push({ table: node.id, column: col.name, type, reason });
          break;
        }
      }
    }
  }

  return result;
}

// â”€â”€â”€ Query Pattern Analysis â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//
// Analyzes the schema graph (nodes + edges) to detect potentially expensive
// query patterns and generate recommendations.
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import type { SchemaNode, SchemaEdge } from "../ai/types";

/**
 * Analyze the schema for commonly problematic query patterns.
 * Returns a list of human-readable warnings.
 */
export function analyzeQueryPatterns(
  nodes: SchemaNode[],
  edges: SchemaEdge[],
): string[] {
  const warnings: string[] = [];

  // 1. Tables with no indexes on FK columns
  const nodesWithFkNoIndex = nodes.filter((n) =>
    n.data.columns.some((c) => c.isForeignKey && !c.isUnique),
  );
  if (nodesWithFkNoIndex.length > 0) {
    warnings.push(
      `Tables ${nodesWithFkNoIndex.map((n) => `"${n.data.label}"`).join(", ")} have foreign key columns with no index â€” JOINs will be slow without indexes.`,
    );
  }

  // 2. Many-to-many without junction table
  for (const edge of edges) {
    if (edge.data?.relationshipType === "many-to-many") {
      // Check if a junction table exists
      const junctionExists = nodes.some(
        (n) =>
          n.id !== edge.source &&
          n.id !== edge.target &&
          n.data.columns.some(
            (c) =>
              c.name === `${edge.source}_id` || c.name === `${edge.target}_id`,
          ),
      );
      if (!junctionExists) {
        warnings.push(
          `Many-to-many relationship between "${edge.source}" and "${edge.target}" requires a junction table (e.g., ${edge.source}_${edge.target}).`,
        );
      }
    }
  }

  // 3. Very wide tables (>15 columns)
  for (const node of nodes) {
    if (node.data.columns.length > 15) {
      warnings.push(
        `Table "${node.data.label}" has ${node.data.columns.length} columns â€” consider vertical partitioning to improve read performance.`,
      );
    }
  }

  // 4. Tables with no relationships (isolated nodes)
  const connectedTables = new Set([
    ...edges.map((e) => e.source),
    ...edges.map((e) => e.target),
  ]);
  const isolated = nodes.filter(
    (n) => !connectedTables.has(n.id) && n.data.columns.length > 1,
  );
  if (isolated.length > 0) {
    warnings.push(
      `Tables ${isolated.map((n) => `"${n.data.label}"`).join(", ")} are isolated (no relationships) â€” verify if they should be connected to other tables.`,
    );
  }

  // 5. Missing pagination-friendly indexes
  for (const node of nodes) {
    const hasCreatedAt = node.data.columns.some((c) => c.name === "created_at");
    const isMainEntity = node.data.columns.length > 4;
    if (!hasCreatedAt && isMainEntity) {
      warnings.push(
        `Table "${node.data.label}" lacks a created_at timestamp â€” pagination queries (ORDER BY created_at) will not be supported.`,
      );
    }
  }

  return warnings;
}

// â”€â”€â”€ Join Complexity Detector â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//
// Analyzes the edge graph to detect deep join chains that could cause
// performance problems. Uses BFS to find the longest paths.
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import type { SchemaNode, SchemaEdge } from "../ai/types";

const COMPLEXITY_THRESHOLD = 3; // Warn if any join chain is deeper than this

/**
 * Build an adjacency list from edges.
 */
function buildAdjacency(edges: SchemaEdge[]): Map<string, string[]> {
  const adj = new Map<string, string[]>();
  for (const edge of edges) {
    if (!adj.has(edge.source)) adj.set(edge.source, []);
    adj.get(edge.source)!.push(edge.target);
    // Add reverse direction too
    if (!adj.has(edge.target)) adj.set(edge.target, []);
    adj.get(edge.target)!.push(edge.source);
  }
  return adj;
}

/**
 * BFS to find the longest path from a starting node (unweighted).
 */
function bfsMaxDepth(
  start: string,
  adj: Map<string, string[]>,
): { depth: number; path: string[] } {
  const visited = new Set<string>();
  const queue: { node: string; path: string[] }[] = [
    { node: start, path: [start] },
  ];
  let maxDepth = 0;
  let maxPath: string[] = [start];

  visited.add(start);

  while (queue.length > 0) {
    const { node, path } = queue.shift()!;
    const neighbors = adj.get(node) ?? [];

    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        const newPath = [...path, neighbor];
        if (newPath.length > maxDepth + 1) {
          maxDepth = newPath.length - 1;
          maxPath = newPath;
        }
        queue.push({ node: neighbor, path: newPath });
      }
    }
  }

  return { depth: maxDepth, path: maxPath };
}

/**
 * Detect join chains that exceed the complexity threshold.
 * Returns human-readable warnings.
 */
export function detectJoinComplexity(edges: SchemaEdge[]): string[] {
  if (edges.length === 0) return [];

  const adj = buildAdjacency(edges);
  const warnings: string[] = [];
  const checked = new Set<string>();

  for (const startNode of adj.keys()) {
    if (checked.has(startNode)) continue;

    const { depth, path } = bfsMaxDepth(startNode, adj);

    if (depth >= COMPLEXITY_THRESHOLD) {
      warnings.push(
        `Deep join chain detected (depth ${depth}): ${path.join(" â†’ ")}. ` +
          `Consider denormalizing frequently accessed data or adding a materialized view.`,
      );
    }

    // Mark all nodes in this connected component as checked
    path.forEach((n) => checked.add(n));
  }

  return warnings;
}

/**
 * Calculate a join complexity score (0-100, lower is better).
 */
export function getJoinComplexityScore(edges: SchemaEdge[]): number {
  if (edges.length === 0) return 100;

  const adj = buildAdjacency(edges);
  let maxDepth = 0;

  for (const startNode of adj.keys()) {
    const { depth } = bfsMaxDepth(startNode, adj);
    if (depth > maxDepth) maxDepth = depth;
  }

  // Score degrades above depth 2
  if (maxDepth <= 2) return 100;
  if (maxDepth === 3) return 80;
  if (maxDepth === 4) return 60;
  if (maxDepth === 5) return 40;
  return 20;
}

// â”€â”€â”€ N+1 Query Risk Detector â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//
// Detects schema patterns that commonly lead to N+1 query problems at the
// ORM/application layer. Returns actionable risk descriptions.
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import type { SchemaNode, SchemaEdge } from "../ai/types";

/**
 * Detect N+1 query risks in the schema.
 * Returns a list of risk descriptions.
 */
export function detectNPlusOne(
  nodes: SchemaNode[],
  edges: SchemaEdge[],
): string[] {
  const risks: string[] = [];

  // Build a map of how many children each table has
  const childCount = new Map<string, string[]>();
  for (const edge of edges) {
    if (!childCount.has(edge.target)) childCount.set(edge.target, []);
    childCount.get(edge.target)!.push(edge.source);
  }

  // 1. Tables with many children (fan-out risk)
  for (const [parent, children] of childCount.entries()) {
    if (children.length >= 3) {
      risks.push(
        `N+1 Risk: "${parent}" has ${children.length} child tables (${children.join(", ")}). ` +
          `Fetching lists of ${parent} and then loading children in a loop will cause N+1 queries. ` +
          `Use eager loading (JOIN) or data loaders.`,
      );
    }
  }

  // 2. Many-to-many relationships (both sides get loaded separately)
  const m2mEdges = edges.filter(
    (e) => e.data?.relationshipType === "many-to-many",
  );
  for (const edge of m2mEdges) {
    risks.push(
      `N+1 Risk: Many-to-many between "${edge.source}" and "${edge.target}". ` +
        `Loading ${edge.source} records and then fetching associated ${edge.target} records in a loop creates N+1 queries. ` +
        `Use a batch-loading strategy or preload via JOIN on the junction table.`,
    );
  }

  // 3. Nested one-to-many chains (grandchild tables)
  const parentOf = new Map<string, string[]>();
  for (const edge of edges) {
    if (!parentOf.has(edge.source)) parentOf.set(edge.source, []);
    parentOf.get(edge.source)!.push(edge.target);
  }

  for (const node of nodes) {
    const directParents = parentOf.get(node.id) ?? [];
    for (const parent of directParents) {
      const grandParents = parentOf.get(parent) ?? [];
      if (grandParents.length > 0) {
        risks.push(
          `N+1 Risk: "${node.data.label}" â†’ "${parent}" â†’ "${grandParents[0]}" is a 3-level deep chain. ` +
            `Traversing this relationship naively will cause nested N+1 problems. ` +
            `Use query batching or a single complex JOIN.`,
        );
        break; // one warning per node is enough
      }
    }
  }

  // 4. Self-referencing tables (hierarchical data)
  for (const node of nodes) {
    const selfRef = node.data.columns.find(
      (c) =>
        c.isForeignKey &&
        c.name.toLowerCase().includes(node.id.toLowerCase().replace(/s$/, "")),
    );
    if (selfRef) {
      risks.push(
        `N+1 Risk: "${node.data.label}" has a self-referencing foreign key (${selfRef.name}). ` +
          `Recursive tree traversals will cause severe N+1 problems. ` +
          `Use recursive CTEs (WITH RECURSIVE) instead of application-level loops.`,
      );
    }
  }

  return risks;
}

// â”€â”€â”€ Completeness Validator â€” Ensure all requested tables are generated â”€â”€â”€â”€â”€â”€
//
// Compares user-requested entities against AI-generated tables.
// Flags missing tables and optionally triggers regeneration with corrections.
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import { extractRequiredEntities, extractEntities } from "./entityExtractor";
import type { SchemaNode } from "@/lib/ai/types";

export interface CompletenessReport {
  isComplete: boolean;
  requestedEntities: string[];
  generatedTables: string[];
  missingTables: string[];
  unexpectedTables: string[];
  matchPercentage: number;
}

/**
 * Validate that generated schema includes all requested entities
 */
export function validateCompletenessOfSchema(
  originalPrompt: string,
  generatedNodes: SchemaNode[],
): CompletenessReport {
  // Extract what the user asked for
  const requestedEntities = extractRequiredEntities(originalPrompt);

  // Extract what was actually generated
  const generatedTables = extractTableNamesFromNodes(generatedNodes);

  // Find missing and extra tables
  const missingTables = findMissing(requestedEntities, generatedTables);
  const unexpectedTables = findExtra(requestedEntities, generatedTables);

  // Calculate match percentage
  const matchPercentage =
    requestedEntities.length > 0
      ? ((requestedEntities.length - missingTables.length) /
          requestedEntities.length) *
        100
      : 100;

  return {
    isComplete: missingTables.length === 0,
    requestedEntities,
    generatedTables,
    missingTables,
    unexpectedTables,
    matchPercentage,
  };
}

/**
 * Extract table names from ReactFlow nodes
 */
export function extractTableNamesFromNodes(nodes: SchemaNode[]): string[] {
  return nodes
    .filter((node) => node.type === "tableNode")
    .map((node) => normalizeTableName(node.id))
    .filter((name): name is string => name !== null);
}

/**
 * Normalize a table name for comparison
 */
function normalizeTableName(name: string | undefined): string | null {
  if (!name) return null;

  // Remove underscores, convert to lowercase, singularize
  const normalized = name.toLowerCase().replace(/_/g, "").replace(/s$/, ""); // Simple singularization

  return normalized.length > 0 ? normalized : null;
}

/**
 * Find entities requested but not generated
 */
function findMissing(requested: string[], generated: string[]): string[] {
  const normalizedGenerated = new Set(
    generated
      .map((t) => normalizeTableName(t))
      .filter((t): t is string => t !== null),
  );

  return requested.filter((entity) => {
    const normalized = normalizeTableName(entity);
    return normalized === null || !normalizedGenerated.has(normalized);
  });
}

/**
 * Find tables generated that weren't requested (may be auxiliary/support tables)
 */
function findExtra(requested: string[], generated: string[]): string[] {
  const normalizedRequested = new Set(
    requested
      .map((e) => normalizeTableName(e))
      .filter((e): e is string => e !== null),
  );

  return generated.filter((table) => {
    const normalized = normalizeTableName(table);
    return (
      normalized &&
      !normalizedRequested.has(normalized) &&
      !isAuxiliaryTable(table)
    );
  });
}

/**
 * Check if a table is an auxiliary/support table (not a user-requested entity)
 */
function isAuxiliaryTable(tableName: string): boolean {
  const auxiliary = [
    // Linking tables for many-to-many relationships
    "association",
    "junction",
    "mapping",
    "link",
    "relationship",
    "_",
    // Support tables
    "history",
    "audit",
    "log",
    "cache",
    "session",
    "token",
    "queue",
    "notification",
    "email",
    "preference",
    "setting",
  ];

  const normalized = normalizeTableName(tableName);
  return auxiliary.some((aux) => normalized?.includes(aux));
}

/**
 * Generate a detailed report for the user
 */
export function formatCompletenessReport(report: CompletenessReport): string {
  const lines: string[] = [];

  lines.push(`\nâœ… **Schema Completeness Report**\n`);
  lines.push(`ðŸ“Š Match Rate: **${report.matchPercentage.toFixed(0)}%**\n`);

  if (report.isComplete) {
    lines.push(`âœ“ **All requested entities found!**`);
  } else {
    lines.push(`âš  **Missing ${report.missingTables.length} table(s):**`);
    report.missingTables.forEach((table) => {
      lines.push(`  - ${table}`);
    });
  }

  if (report.unexpectedTables.length > 0) {
    lines.push(`\nðŸ“ Additional tables (automatically added):`);
    report.unexpectedTables.forEach((table) => {
      lines.push(`  - ${table}`);
    });
  }

  lines.push(`\n**Requested Entities (${report.requestedEntities.length}):**`);
  lines.push(report.requestedEntities.map((e) => `  - ${e}`).join("\n"));

  lines.push(`\n**Generated Tables (${report.generatedTables.length}):**`);
  lines.push(report.generatedTables.map((t) => `  - ${t}`).join("\n"));

  return lines.join("\n");
}

/**
 * Suggest a corrective prompt to fix missing tables
 */
export function generateCorrectivePrompt(
  originalPrompt: string,
  report: CompletenessReport,
): string {
  if (report.isComplete) {
    return originalPrompt; // No correction needed
  }

  const missing = report.missingTables;
  let corrective = originalPrompt;

  // Add explicit reminder about missing tables
  corrective += `\n\nðŸ”´ **CRITICAL**: The previous schema was missing these required tables:`;
  missing.forEach((table) => {
    corrective += `\n- ${table}`;
  });

  corrective += `\n\nPlease MUST include these tables in your regenerated schema. Do not skip any of them.`;
  corrective += `\n\nHere are the tables that MUST be present in the final schema:`;
  report.requestedEntities.forEach((entity) => {
    corrective += `\n- ${entity}`;
  });

  return corrective;
}

/**
 * Create a side-by-side comparison for debugging
 */
export function createComparisonTable(report: CompletenessReport): string {
  const maxRows = Math.max(
    report.requestedEntities.length,
    report.generatedTables.length,
  );
  const lines: string[] = [];

  lines.push("| Requested Entity | Generated Table | Status |");
  lines.push("|---|---|---|");

  for (let i = 0; i < maxRows; i++) {
    const entity = report.requestedEntities[i] || "-";
    const table = report.generatedTables[i] || "-";
    const status =
      report.requestedEntities[i] && report.generatedTables[i]
        ? "âœ“"
        : report.requestedEntities[i] && !report.generatedTables[i]
          ? "âœ— MISSING"
          : report.generatedTables[i]
            ? "âœ“ EXTRA"
            : "-";

    lines.push(`| ${entity} | ${table} | ${status} |`);
  }

  return lines.join("\n");
}

