/**
 * Extract all entities/tables mentioned in a user's prompt
 */
export function extractEntities(prompt: string): ExtractedEntity[] {
  const entities = new Map<string, ExtractedEntity>();

  // Tokenize prompt
  const tokens = prompt
    .toLowerCase()
    .replace(/[^\w\s]/g, " ")
    .split(/\s+/)
    .filter((t) => t.length > 0);

  // Track multi-word patterns like "order items" or "product customizations"
  for (let i = 0; i < tokens.length; i++) {
    const word = tokens[i];

    // Skip excluded words
    if (EXCLUDED_KEYWORDS.has(word)) continue;

    // Check if it's a known entity keyword
    if (HIGH_CONFIDENCE_KEYWORDS.has(word)) {
      const singular = PLURAL_MAP[word] || word;
      addOrUpdateEntity(entities, singular, word, 0.95);
      continue;
    }

    // Try two-word combinations for compound entities
    if (i < tokens.length - 1) {
      const twoWord = `${word} ${tokens[i + 1]}`;
      if (!EXCLUDED_KEYWORDS.has(tokens[i + 1])) {
        // Check if either word is high-confidence
        if (
          HIGH_CONFIDENCE_KEYWORDS.has(word) ||
          HIGH_CONFIDENCE_KEYWORDS.has(tokens[i + 1])
        ) {
          const singular = singularize(twoWord);
          addOrUpdateEntity(entities, singular, twoWord, 0.85);
        }
      }
    }

    // Check if it's a potential entity even if not in keyword list
    // (e.g., domain-specific words like "barista", "roaster", "blend")
    if (word.length > 3 && !isLikelyAdjective(word)) {
      // Calculate confidence based on context
      const confidence = calculateEntityConfidence(word, tokens, i);
      if (confidence > 0.6) {
        addOrUpdateEntity(entities, singularize(word), word, confidence);
      }
    }
  }

  // Also check for explicit "Table: X" or "Entity: X" patterns
  const tablePattern = /(?:table|entity|model|collection):\s*(\w+)/gi;
  let match;
  while ((match = tablePattern.exec(prompt)) !== null) {
    const tableName = match[1].toLowerCase();
    addOrUpdateEntity(entities, singularize(tableName), tableName, 0.99);
  }

  // Also check for "X table" or "X entity" patterns
  const explicitPattern = /(\w+)\s+(?:table|entity|model|collection)\b/gi;
  const seen = new Set<string>();
  while ((match = explicitPattern.exec(prompt)) !== null) {
    const tableName = match[1].toLowerCase();
    if (!seen.has(tableName)) {
      addOrUpdateEntity(entities, singularize(tableName), tableName, 0.98);
      seen.add(tableName);
    }
  }

  // Convert to array and sort by confidence
  const result = Array.from(entities.values()).sort(
    (a, b) => b.confidence - a.confidence,
  );

  return result;
}

/**
 * Normalize plural form to singular
 */
function singularize(word: string): string {
  if (PLURAL_MAP[word]) {
    return PLURAL_MAP[word];
  }

  // Simple heuristics
  if (word.endsWith("ies")) {
    return word.slice(0, -3) + "y";
  }
  if (word.endsWith("es")) {
    return word.slice(0, -2);
  }
  if (word.endsWith("s")) {
    return word.slice(0, -1);
  }

  return word;
}

/**
 * Check if a word is likely an adjective (not an entity)
 */
function isLikelyAdjective(word: string): boolean {
  const adjectives = new Set([
    "large",
    "small",
    "big",
    "unique",
    "unique",
    "special",
    "required",
    "optional",
    "primary",
    "secondary",
    "main",
    "new",
    "old",
    "active",
    "inactive",
    "available",
    "unavailable",
    "complete",
    "incomplete",
    "valid",
    "invalid",
  ]);
  return adjectives.has(word);
}

/**
 * Calculate confidence that a word is a database entity
 */
function calculateEntityConfidence(
  word: string,
  tokens: string[],
  index: number,
): number {
  let confidence = 0.5;

  // Capitalized words are more likely entities
  if (word !== word.toLowerCase()) {
    confidence += 0.15;
  }

  // Words near high-confidence keywords are likely entities too
  const neighbors = [tokens[index - 1] || "", tokens[index + 1] || ""];
  if (neighbors.some((n) => HIGH_CONFIDENCE_KEYWORDS.has(n))) {
    confidence += 0.2;
  }

  // Words that end in "-tion", "-ment", "-ance" are often entities
  if (
    word.endsWith("tion") ||
    word.endsWith("ment") ||
    word.endsWith("ance") ||
    word.endsWith("ence")
  ) {
    confidence += 0.1;
  }

  return Math.min(confidence, 0.9);
}

/**
 * Helper: add or update an entity in the map
 */
function addOrUpdateEntity(
  entities: Map<string, ExtractedEntity>,
  singular: string,
  variant: string,
  confidence: number,
): void {
  const existing = entities.get(singular);

  if (existing) {
    existing.variants.push(variant);
    existing.frequency++;
    existing.confidence = Math.max(existing.confidence, confidence);
  } else {
    entities.set(singular, {
      name: singular,
      variants: [variant],
      confidence,
      frequency: 1,
    });
  }
}

/**
 * Extract required entities from prompt (higher threshold)
 */
export function extractRequiredEntities(prompt: string): string[] {
  return extractEntities(prompt)
    .filter((e) => e.confidence >= 0.75)
    .map((e) => e.name);
}

/**
 * Generate a user-friendly summary of extracted entities
 */
export function summarizeExtractedEntities(
  entities: ExtractedEntity[],
): string {
  if (entities.length === 0) {
    return "No database entities detected.";
  }

  const names = entities.slice(0, 10).map((e) => e.name);
  const remaining = Math.max(0, entities.length - 10);

  let summary = `Detected entities: ${names.join(", ")}`;
  if (remaining > 0) {
    summary += ` (+ ${remaining} more)`;
  }

  return summary;
}

// â”€â”€â”€ DB-backed Prompt Cache â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//
// Stores AI responses in the `ai_cache` PostgreSQL table.
// Cache key = sha256(normalized_prompt + task_type)
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

import { createHash } from "crypto";
import { query } from "../db";

export type CacheTaskType = "generate" | "analyze" | "refine" | "review";

// â”€â”€â”€ Hash helper â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

function buildHash(normalizedPrompt: string, taskType: CacheTaskType): string {
  return createHash("sha256")
    .update(`${taskType}::${normalizedPrompt}`)
    .digest("hex");
}

// â”€â”€â”€ In-memory L1 cache (same process, 5-min TTL) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

const L1_TTL_MS = 5 * 60 * 1000;
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const l1: Map<string, { data: any; ts: number }> = new Map();
let cacheSchemaReady = false;
let cacheSchemaInitPromise: Promise<void> | null = null;

function l1Get(hash: string): unknown | null {
  const entry = l1.get(hash);
  if (!entry) return null;
  if (Date.now() - entry.ts > L1_TTL_MS) {
    l1.delete(hash);
    return null;
  }
  return entry.data;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function l1Set(hash: string, data: any): void {
  l1.set(hash, { data, ts: Date.now() });
}

async function ensureCacheSchema(): Promise<void> {
  if (cacheSchemaReady) return;

  if (!cacheSchemaInitPromise) {
    cacheSchemaInitPromise = (async () => {
      await query(`
        CREATE TABLE IF NOT EXISTS ai_cache (
          id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
          prompt_hash   VARCHAR(64) NOT NULL,
          task_type     VARCHAR(20) NOT NULL,
          response_json JSONB NOT NULL,
          created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          UNIQUE (prompt_hash, task_type)
        )
      `);

      await query(
        `CREATE INDEX IF NOT EXISTS idx_ai_cache_hash_type ON ai_cache (prompt_hash, task_type)`,
      );
      await query(
        `CREATE INDEX IF NOT EXISTS idx_ai_cache_created ON ai_cache (created_at)`,
      );

      cacheSchemaReady = true;
      console.log("[PromptCache] ai_cache schema verified");
    })().catch((err) => {
      cacheSchemaInitPromise = null;
      throw err;
    });
  }

  await cacheSchemaInitPromise;
}

// â”€â”€â”€ DB helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

/**
 * Check DB cache. Returns cached JSON or null.
 */
export async function promptCacheGet(
  normalizedPrompt: string,
  taskType: CacheTaskType,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
): Promise<any | null> {
  const hash = buildHash(normalizedPrompt, taskType);

  // L1 first
  const l1Hit = l1Get(hash);
  if (l1Hit) return l1Hit;

  try {
    await ensureCacheSchema();

    const result = await query<{ response_json: unknown }>(
      `SELECT response_json FROM ai_cache
       WHERE prompt_hash = $1 AND task_type = $2
       LIMIT 1`,
      [hash, taskType],
    );

    if (result.rowCount && result.rowCount > 0) {
      const data = result.rows[0].response_json;
      l1Set(hash, data);
      console.log(`[PromptCache] DB hit â€” ${taskType} ${hash.slice(0, 8)}`);
      return data;
    }
  } catch (err) {
    console.warn("[PromptCache] DB read error (non-fatal):", err);
  }

  return null;
}

/**
 * Write a result into the DB cache.
 */
export async function promptCacheSet(
  normalizedPrompt: string,
  taskType: CacheTaskType,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  data: any,
): Promise<void> {
  const hash = buildHash(normalizedPrompt, taskType);
  l1Set(hash, data);

  try {
    await ensureCacheSchema();

    await query(
      `INSERT INTO ai_cache (prompt_hash, task_type, response_json, created_at)
       VALUES ($1, $2, $3, NOW())
       ON CONFLICT (prompt_hash, task_type) DO UPDATE
         SET response_json = EXCLUDED.response_json,
             created_at    = NOW()`,
      [hash, taskType, JSON.stringify(data)],
    );
    console.log(`[PromptCache] DB written â€” ${taskType} ${hash.slice(0, 8)}`);
  } catch (err) {
    console.warn("[PromptCache] DB write error (non-fatal):", err);
  }
}

/**
 * Purge all cache entries older than the given number of days.
 */
export async function purgeOldCache(olderThanDays = 30): Promise<number> {
  try {
    await ensureCacheSchema();

    const res = await query(
      `DELETE FROM ai_cache WHERE created_at < NOW() - INTERVAL '${olderThanDays} days'`,
    );
    return res.rowCount ?? 0;
  } catch (err) {
    console.warn("[PromptCache] Purge error:", err);
    return 0;
  }
}

