// â”€â”€â”€ Clarity Score Calculator â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

interface ClarityResult {
  score: number;
  suggestions: string[];
  detectedEntities: string[];
  detectedRelationships: string[];
}

export function calculateClarity(description: string): ClarityResult {
  const suggestions: string[] = [];
  const detectedEntities: string[] = [];
  const detectedRelationships: string[] = [];
  let score = 0;

  if (!description.trim()) {
    return {
      score: 0,
      suggestions: ["Start by describing what your application does."],
      detectedEntities: [],
      detectedRelationships: [],
    };
  }

  // Length check
  const words = description.trim().split(/\s+/).length;
  if (words < 5) {
    suggestions.push(
      "Add more detail â€” describe the main things your app manages.",
    );
  } else if (words < 15) {
    score += 10;
    suggestions.push(
      "Good start. Try mentioning how things relate to each other.",
    );
  } else if (words < 30) {
    score += 20;
  } else {
    score += 30;
  }

  // Entity detection
  const entityKeywords = [
    "user",
    "users",
    "customer",
    "customers",
    "account",
    "accounts",
    "product",
    "products",
    "item",
    "items",
    "order",
    "orders",
    "purchase",
    "purchases",
    "post",
    "posts",
    "article",
    "articles",
    "blog",
    "comment",
    "comments",
    "review",
    "reviews",
    "category",
    "categories",
    "tag",
    "tags",
    "payment",
    "payments",
    "transaction",
    "transactions",
    "inventory",
    "stock",
    "warehouse",
    "class",
    "classes",
    "course",
    "courses",
    "lesson",
    "lessons",
    "teacher",
    "teachers",
    "student",
    "students",
    "assignment",
    "assignments",
    "submission",
    "submissions",
    "message",
    "messages",
    "chat",
    "conversation",
    "team",
    "teams",
    "organization",
    "company",
    "project",
    "projects",
    "task",
    "tasks",
    "file",
    "files",
    "document",
    "documents",
    "address",
    "addresses",
    "location",
    "locations",
    "wishlist",
    "cart",
    "shipping",
  ];

  const lowerDesc = description.toLowerCase();
  for (const keyword of entityKeywords) {
    if (lowerDesc.includes(keyword) && !detectedEntities.includes(keyword)) {
      detectedEntities.push(keyword);
    }
  }

  if (detectedEntities.length === 0) {
    suggestions.push(
      "Mention the main things your app manages (e.g., users, products, orders).",
    );
  } else if (detectedEntities.length < 3) {
    score += 15;
    suggestions.push("Try adding more entities for a richer schema.");
  } else if (detectedEntities.length < 5) {
    score += 25;
  } else {
    score += 35;
  }

  // Relationship detection
  const relationshipKeywords = [
    "has",
    "have",
    "belongs to",
    "contains",
    "owns",
    "manages",
    "placed by",
    "created by",
    "assigned to",
    "connected to",
    "references",
    "links to",
    "relates to",
    "part of",
    "who",
    "which",
    "with",
    "their",
    "each",
  ];

  for (const keyword of relationshipKeywords) {
    if (lowerDesc.includes(keyword)) {
      detectedRelationships.push(keyword);
    }
  }

  if (detectedRelationships.length === 0) {
    suggestions.push(
      "Describe how things relate (e.g., 'users place orders', 'orders contain products').",
    );
  } else if (detectedRelationships.length < 2) {
    score += 10;
  } else {
    score += 20;
  }

  // Constraints / details detection
  const constraintKeywords = [
    "unique",
    "required",
    "optional",
    "default",
    "not null",
    "index",
    "track",
    "tracking",
  ];
  let hasConstraints = false;
  for (const keyword of constraintKeywords) {
    if (lowerDesc.includes(keyword)) {
      hasConstraints = true;
      break;
    }
  }

  if (hasConstraints) {
    score += 15;
  } else if (score > 40) {
    suggestions.push(
      "Consider mentioning constraints (e.g., 'email must be unique', 'track creation date').",
    );
  }

  // Cap score
  score = Math.min(score, 100);

  if (score >= 70 && suggestions.length === 0) {
    suggestions.push("Looking great! Hit Generate to create your schema.");
  }

  return { score, suggestions, detectedEntities, detectedRelationships };
}

