      keywords: ["project", "projects"],
      columns: () => [
        makePK(),
        {
          id: nextId(),
          name: "name",
          type: "VARCHAR",
          isPrimaryKey: false,
          isForeignKey: false,
          isNullable: false,
          isUnique: false,
        },
        {
          id: nextId(),
          name: "description",
          type: "TEXT",
          isPrimaryKey: false,
          isForeignKey: false,
          isNullable: true,
          isUnique: false,
        },
        makeFK("users"),
        ...makeTimestamps(),
