// â”€â”€â”€ SQL Export â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export function exportSchema(
  tables: TableSchema[],
  format: ExportFormat,
): string {
  const lines: string[] = [];

  lines.push(`-- Generated by EasySchema`);
  lines.push(`-- Format: ${format.toUpperCase()}`);
  lines.push(`-- Tables: ${tables.length}`);
  lines.push(``);

  for (const table of tables) {
    lines.push(generateCreateTable(table, format));
    lines.push(``);
  }

  return lines.join("\n");
}

function generateCreateTable(table: TableSchema, format: ExportFormat): string {
  const lines: string[] = [];
  lines.push(`CREATE TABLE ${table.name} (`);

  const colDefs: string[] = [];
  const constraints: string[] = [];

  for (const col of table.columns) {
    let def = `  ${col.name} ${mapType(col.type, format)}`;

    if (col.isPrimaryKey) {
      if (format === "postgresql") {
        def = `  ${col.name} ${col.type === "SERIAL" ? "SERIAL" : mapType(col.type, format)} PRIMARY KEY`;
      } else if (format === "mysql") {
        def = `  ${col.name} INT AUTO_INCREMENT PRIMARY KEY`;
      } else {
        def = `  ${col.name} INTEGER PRIMARY KEY AUTOINCREMENT`;
      }
    } else {
      if (!col.isNullable) def += " NOT NULL";
      if (col.isUnique) def += " UNIQUE";
      if (col.defaultValue) {
        if (col.defaultValue === "NOW()") {
          def +=
            format === "mysql"
              ? " DEFAULT CURRENT_TIMESTAMP"
              : " DEFAULT NOW()";
        } else {
          def += ` DEFAULT ${col.defaultValue}`;
        }
      }
    }

    colDefs.push(def);

    if (col.isForeignKey && col.references) {
      constraints.push(
        `  FOREIGN KEY (${col.name}) REFERENCES ${col.references.table}(${col.references.column})`,
      );
    }
  }

  lines.push([...colDefs, ...constraints].join(",\n"));
  lines.push(`);`);

  return lines.join("\n");
}

function mapType(type: ColumnType, format: ExportFormat): string {
  const typeMap: Record<ExportFormat, Record<string, string>> = {
    postgresql: {
      INT: "INTEGER",
      BIGINT: "BIGINT",
      SERIAL: "SERIAL",
      TEXT: "TEXT",
      VARCHAR: "VARCHAR(255)",
      BOOLEAN: "BOOLEAN",
      DATE: "DATE",
      TIMESTAMP: "TIMESTAMP",
      FLOAT: "REAL",
      DECIMAL: "DECIMAL(10,2)",
      JSON: "JSONB",
      UUID: "UUID",
    },
    mysql: {
      INT: "INT",
      BIGINT: "BIGINT",
      SERIAL: "INT AUTO_INCREMENT",
      TEXT: "TEXT",
      VARCHAR: "VARCHAR(255)",
      BOOLEAN: "TINYINT(1)",
      DATE: "DATE",
      TIMESTAMP: "TIMESTAMP",
      FLOAT: "FLOAT",
      DECIMAL: "DECIMAL(10,2)",
      JSON: "JSON",
      UUID: "CHAR(36)",
    },
    sqlite: {
      INT: "INTEGER",
      BIGINT: "INTEGER",
      SERIAL: "INTEGER",
      TEXT: "TEXT",
      VARCHAR: "TEXT",
      BOOLEAN: "INTEGER",
      DATE: "TEXT",
      TIMESTAMP: "DATETIME",
      FLOAT: "REAL",
      DECIMAL: "REAL",
      JSON: "TEXT",
      UUID: "TEXT",
    },
  };

  return typeMap[format][type] || type;
}

// â”€â”€â”€ Join Table Generator â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export function generateJoinTable(
  tableA: TableSchema,
  tableB: TableSchema,
): TableSchema {
  const name = `${tableA.name}_${tableB.name}`;
  const pkA = tableA.columns.find((c) => c.isPrimaryKey);
  const pkB = tableB.columns.find((c) => c.isPrimaryKey);

  const columns: Column[] = [
    {
      id: `jt-${name}-id`,
      name: "id",
      type: "SERIAL",
      isPrimaryKey: true,
      isForeignKey: false,
      isNullable: false,
      isUnique: true,
    },
    {
      id: `jt-${name}-${tableA.name}_id`,
      name: `${tableA.name}_id`,
      type: pkA?.type === "BIGINT" ? "BIGINT" : "INT",
      isPrimaryKey: false,
      isForeignKey: true,
      isNullable: false,
      isUnique: false,
      references: { table: tableA.id, column: pkA?.name ?? "id" },
    },
    {
      id: `jt-${name}-${tableB.name}_id`,
      name: `${tableB.name}_id`,
      type: pkB?.type === "BIGINT" ? "BIGINT" : "INT",
      isPrimaryKey: false,
      isForeignKey: true,
      isNullable: false,
      isUnique: false,
      references: { table: tableB.id, column: pkB?.name ?? "id" },
    },
    {
      id: `jt-${name}-created`,
      name: "created_at",
      type: "TIMESTAMP",
      isPrimaryKey: false,
      isForeignKey: false,
      isNullable: false,
      isUnique: false,
      defaultValue: "NOW()",
    },
  ];

  return {
    id: `jt-${Date.now()}`,
    name,
    columns,
    position: {
      x: (tableA.position.x + tableB.position.x) / 2,
      y: Math.max(tableA.position.y, tableB.position.y) + 280,
    },
  };
}

